#!/usr/bin/env node
/**
 * Raises Gradle / Kotlin daemon memory limits in the native Android project
 * generated by `expo prebuild`. Idempotent.
 *
 * Root cause: Expo's default android/gradle.properties ships with
 *   org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m
 * Release builds run KSP (expo-updates:kspReleaseKotlin), lintVital, R8 and
 * CMake in parallel. 512m of Metaspace is exhausted, failing the build with
 * `java.lang.OutOfMemoryError: Metaspace`.
 *
 * Strategy: upsert memory-related keys in android/gradle.properties,
 * preserving every other key Expo generated. Safe to run after every
 * `expo prebuild --clean` since android/ is regenerated on CI.
 *
 * Usage:
 *   node scripts/patch-android-memory.mjs
 *
 * Overrides via env (optional):
 *   GRADLE_XMX            (default "4g")
 *   GRADLE_METASPACE      (default "1g")
 *   KOTLIN_DAEMON_XMX     (default "2g")
 *   KOTLIN_DAEMON_METASPACE (default "512m")
 *   GRADLE_WORKERS_MAX    (default "2")
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ROOT = process.cwd();
const FILE = join(ROOT, "android", "gradle.properties");

const XMX = process.env.GRADLE_XMX ?? "4g";
const METASPACE = process.env.GRADLE_METASPACE ?? "1g";
const KOTLIN_XMX = process.env.KOTLIN_DAEMON_XMX ?? "2g";
const KOTLIN_METASPACE = process.env.KOTLIN_DAEMON_METASPACE ?? "512m";
const WORKERS_MAX = process.env.GRADLE_WORKERS_MAX ?? "2";

/** Keys we manage. Values are (re)written on every run. */
const MANAGED = {
	"org.gradle.jvmargs": `-Xmx${XMX} -XX:MaxMetaspaceSize=${METASPACE} -XX:+HeapDumpOnOutOfMemoryError -Dfile.encoding=UTF-8`,
	"kotlin.daemon.jvmargs": `-Xmx${KOTLIN_XMX} -XX:MaxMetaspaceSize=${KOTLIN_METASPACE} -Dfile.encoding=UTF-8`,
	"org.gradle.caching": "true",
	"org.gradle.parallel": "true",
	"org.gradle.workers.max": WORKERS_MAX,
};

const MARKER = "# >>> rd-manager:gradle-memory-patch";
const CLOSER = "# <<< rd-manager:gradle-memory-patch";

if (!existsSync(FILE)) {
	console.error(
		`patch-android-memory: ${FILE} not found. Run \`npx expo prebuild\` first.`,
	);
	process.exit(1);
}

let original = readFileSync(FILE, "utf8");
// Strip any prior patch block so re-runs stay idempotent.
if (original.includes(MARKER)) {
	const start = original.indexOf(MARKER);
	const end = original.indexOf(CLOSER);
	if (end !== -1) {
		const lineEnd = original.indexOf("\n", end + CLOSER.length);
		original =
			original.slice(0, start) +
			original.slice(lineEnd === -1 ? original.length : lineEnd + 1);
	}
}

// Remove existing occurrences of managed keys (commented lines left alone).
const lines = original.split("\n").filter((line) => {
	const trimmed = line.trim();
	for (const key of Object.keys(MANAGED)) {
		if (
			trimmed === key ||
			trimmed.startsWith(`${key}=`) ||
			trimmed.startsWith(`${key} `)
		) {
			return false;
		}
	}
	return true;
});

while (lines.length > 0 && lines[lines.length - 1].trim() === "") lines.pop();

const block = [
	"",
	MARKER,
	"# Raised limits: expo-updates KSP + lintVital + R8 OOM with default 512m Metaspace.",
	...Object.entries(MANAGED).map(([k, v]) => `${k}=${v}`),
	CLOSER,
	"",
].join("\n");

writeFileSync(FILE, `${lines.join("\n")}\n${block}`, "utf8");
console.log(`patch-android-memory: tuned Gradle memory in ${FILE}`);
for (const [k, v] of Object.entries(MANAGED)) console.log(`  ${k}=${v}`);
